--
-- Table structure for table `practice`
--

DROP TABLE IF EXISTS `practice`;
/*!40101 SET @saved_cs_client = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `practice`
(
    `id`             bigint      NOT NULL AUTO_INCREMENT,
    `student_id`     bigint      NOT NULL,
    `course_id`      bigint      NOT NULL,
    `source_type`    varchar(16) NOT NULL,
    `status`         varchar(16) NOT NULL DEFAULT 'IN_PROGRESS',
    `question_count` int         NOT NULL,
    `correct_count`  int                  DEFAULT NULL,
    `started_at`     datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `submitted_at`   datetime(3)          DEFAULT NULL,
    `chapter_id`     bigint               DEFAULT NULL,
    `archived`       tinyint     NOT NULL DEFAULT '0',
    PRIMARY KEY (`id`),
    KEY `idx_student_history` (`student_id`, `status`, `submitted_at`, `id`),
    KEY `idx_course_history` (`course_id`, `status`, `submitted_at`, `id`),
    KEY `fk_practice_chapter` (`chapter_id`),
    CONSTRAINT `fk_practice_chapter` FOREIGN KEY (`chapter_id`) REFERENCES `chapter` (`id`),
    CONSTRAINT `practice_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `app_user` (`id`),
    CONSTRAINT `practice_ibfk_2` FOREIGN KEY (`course_id`) REFERENCES `course` (`id`),
    CONSTRAINT `ck_practice_source` CHECK ((`source_type` in (_utf8mb4'NORMAL', _utf8mb4'WRONG', _utf8mb4'CHAPTER'))),
    CONSTRAINT `practice_chk_2` CHECK ((`question_count` > 0)),
    CONSTRAINT `practice_chk_3` CHECK ((
        ((`status` = _utf8mb4'IN_PROGRESS') and (`correct_count` is null) and (`submitted_at` is null)) or
        ((`status` = _utf8mb4'SUBMITTED') and (`correct_count` is not null) and
         (`correct_count` between 0 and `question_count`) and (`submitted_at` is not null) and
         (`submitted_at` >= `started_at`)))),
    CONSTRAINT `practice_chk_4` CHECK ((`archived` in (0, 1)))
) ENGINE = InnoDB
  AUTO_INCREMENT = 547
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

