--
-- Table structure for table `practice_item`
--

DROP TABLE IF EXISTS `practice_item`;
/*!40101 SET @saved_cs_client = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `practice_item`
(
    `id`              bigint     NOT NULL AUTO_INCREMENT,
    `practice_id`     bigint     NOT NULL,
    `question_id`     bigint     NOT NULL,
    `order_no`        int        NOT NULL,
    `option_order`    varchar(4) NOT NULL,
    `selected_answer` varchar(4) DEFAULT NULL,
    `is_correct`      tinyint    DEFAULT NULL,
    PRIMARY KEY (`id`),
    UNIQUE KEY `practice_id` (`practice_id`, `order_no`),
    UNIQUE KEY `practice_id_2` (`practice_id`, `question_id`),
    KEY `idx_item_question` (`question_id`),
    CONSTRAINT `practice_item_ibfk_1` FOREIGN KEY (`practice_id`) REFERENCES `practice` (`id`),
    CONSTRAINT `practice_item_ibfk_2` FOREIGN KEY (`question_id`) REFERENCES `question` (`id`),
    CONSTRAINT `practice_item_chk_1` CHECK ((`order_no` > 0)),
    CONSTRAINT `practice_item_chk_2` CHECK ((`option_order` in
                                             (_utf8mb4'AB', _utf8mb4'ABCD', _utf8mb4'ABDC', _utf8mb4'ACBD',
                                              _utf8mb4'ACDB', _utf8mb4'ADBC', _utf8mb4'ADCB', _utf8mb4'BACD',
                                              _utf8mb4'BADC', _utf8mb4'BCAD', _utf8mb4'BCDA', _utf8mb4'BDAC',
                                              _utf8mb4'BDCA', _utf8mb4'CABD', _utf8mb4'CADB', _utf8mb4'CBAD',
                                              _utf8mb4'CBDA', _utf8mb4'CDAB', _utf8mb4'CDBA', _utf8mb4'DABC',
                                              _utf8mb4'DACB', _utf8mb4'DBAC', _utf8mb4'DBCA', _utf8mb4'DCAB',
                                              _utf8mb4'DCBA'))),
    CONSTRAINT `practice_item_chk_3` CHECK (((`is_correct` is null) or (`is_correct` in (0, 1)))),
    CONSTRAINT `practice_item_chk_4` CHECK (((`selected_answer` is null) or (`selected_answer` in
                                                                             (_utf8mb4'A', _utf8mb4'B', _utf8mb4'C',
                                                                              _utf8mb4'D', _utf8mb4'AB', _utf8mb4'AC',
                                                                              _utf8mb4'AD', _utf8mb4'BC', _utf8mb4'BD',
                                                                              _utf8mb4'CD', _utf8mb4'ABC',
                                                                              _utf8mb4'ABD', _utf8mb4'ACD',
                                                                              _utf8mb4'BCD', _utf8mb4'ABCD'))))
) ENGINE = InnoDB
  AUTO_INCREMENT = 10317
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

