--
-- Table structure for table `question`
--

DROP TABLE IF EXISTS `question`;
/*!40101 SET @saved_cs_client = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `question`
(
    `id`             bigint        NOT NULL AUTO_INCREMENT,
    `chapter_id`     bigint        NOT NULL,
    `question_type`  varchar(16)   NOT NULL,
    `stem`           text          NOT NULL,
    `option_a`       varchar(1000) NOT NULL,
    `option_b`       varchar(1000) NOT NULL,
    `option_c`       varchar(1000) DEFAULT NULL,
    `option_d`       varchar(1000) DEFAULT NULL,
    `correct_answer` varchar(4)    NOT NULL,
    `explanation`    text          NOT NULL,
    PRIMARY KEY (`id`),
    KEY `idx_question_chapter` (`chapter_id`, `question_type`),
    CONSTRAINT `question_ibfk_1` FOREIGN KEY (`chapter_id`) REFERENCES `chapter` (`id`),
    CONSTRAINT `question_chk_1` CHECK (((char_length(trim(`stem`)) > 0) and (char_length(trim(`explanation`)) > 0))),
    CONSTRAINT `question_chk_2` CHECK (((char_length(trim(`option_a`)) > 0) and (char_length(trim(`option_b`)) > 0))),
    CONSTRAINT `question_chk_3` CHECK ((
        ((`question_type` in (_utf8mb4'SINGLE', _utf8mb4'MULTIPLE')) and (`option_c` is not null) and
         (`option_d` is not null) and (char_length(trim(`option_c`)) > 0) and (char_length(trim(`option_d`)) > 0)) or
        ((`question_type` = _utf8mb4'JUDGE') and (`option_a` = _utf8mb4'正确') and (`option_b` = _utf8mb4'错误') and
         (`option_c` is null) and (`option_d` is null)))),
    CONSTRAINT `question_chk_4` CHECK ((((`question_type` = _utf8mb4'SINGLE') and
                                         (`correct_answer` in (_utf8mb4'A', _utf8mb4'B', _utf8mb4'C', _utf8mb4'D'))) or
                                        ((`question_type` = _utf8mb4'MULTIPLE') and (`correct_answer` in
                                                                                     (_utf8mb4'AB', _utf8mb4'AC',
                                                                                      _utf8mb4'AD', _utf8mb4'BC',
                                                                                      _utf8mb4'BD', _utf8mb4'CD',
                                                                                      _utf8mb4'ABC', _utf8mb4'ABD',
                                                                                      _utf8mb4'ACD', _utf8mb4'BCD',
                                                                                      _utf8mb4'ABCD'))) or
                                        ((`question_type` = _utf8mb4'JUDGE') and
                                         (`correct_answer` in (_utf8mb4'A', _utf8mb4'B')))))
) ENGINE = InnoDB
  AUTO_INCREMENT = 50521
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

