-- Dumping data for table `question`
--

LOCK TABLES `question` WRITE;
/*!40000 ALTER TABLE `question`
    DISABLE KEYS */;
INSERT INTO `question`
VALUES (1, 11, 'SINGLE', '函数 f(x)=x^2 的导数是？', '2x', 'x', '2', 'x^2', 'A', '幂函数求导得到 2x。'),
       (2, 11, 'MULTIPLE', '以下哪些函数的导数恒为 0？', 'f(x)=1', 'f(x)=5', 'f(x)=x', 'f(x)=x^2', 'AB',
        '常数函数的导数为零。'),
       (3, 11, 'JUDGE', '函数 f(x)=x 的导数恒为 1。', '正确', '错误', NULL, NULL, 'A', '一次函数 x 的导数是 1。'),
       (4, 11, 'SINGLE', '函数 f(x)=3x 的导数是？', '3', 'x', '3x', '0', 'A', '常数倍的求导规则得到 3。'),
       (5, 12, 'SINGLE', '函数 f(x)=2x 的一个原函数是？', 'x^2', '2', '2x^2', 'x', 'A', 'x^2 的导数为 2x。'),
       (6, 12, 'JUDGE', '连续函数在区间上的定积分可以表示带符号的面积。', '正确', '错误', NULL, NULL, 'A',
        '曲线在横轴下方的部分以负面积计入。'),
       (7, 21, 'SINGLE', '查询数据通常使用哪条 SQL 语句？', 'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'A',
        'SELECT 用于查询数据。'),
       (8, 21, 'MULTIPLE', '以下哪些 SQL 语句会修改表中的数据？', 'INSERT', 'UPDATE', 'SELECT', 'DELETE', 'ABD',
        'INSERT 插入，UPDATE 修改，DELETE 删除。'),
       (9, 21, 'JUDGE', 'WHERE 子句可以筛选满足条件的记录。', '正确', '错误', NULL, NULL, 'A',
        'WHERE 指定记录筛选条件。'),
       (10, 21, 'SINGLE', 'SQL 中按列分组使用哪个子句？', 'GROUP BY', 'ORDER BY', 'WHERE', 'LIMIT', 'A',
        'GROUP BY 用于分组，ORDER BY 用于排序。'),
       (11, 22, 'MULTIPLE', '以下哪些属于事务 ACID 性质？', '原子性', '一致性', '隔离性', '持久性', 'ABCD',
        'ACID 包括原子性、一致性、隔离性、持久性。'),
       (12, 22, 'JUDGE', '事务回滚会撤销该事务尚未提交的更改。', '正确', '错误', NULL, NULL, 'A',
        '回滚用于撤销未提交事务的更改。'),
       (13, 31, 'SINGLE', '一个字节通常包含多少位？', '8', '4', '16', '32', 'A', '一个字节为 8 位。'),
       (14, 31, 'MULTIPLE', '以下哪些是二进制数码？', '0', '1', '2', '8', 'AB', '二进制只使用 0 和 1。'),
       (15, 31, 'JUDGE', '十六进制的 F 对应十进制的 15。', '正确', '错误', NULL, NULL, 'A',
        '十六进制数码 A 至 F 分别表示 10 至 15。'),
       (16, 31, 'SINGLE', '二进制 1010 对应的十进制数是？', '10', '8', '12', '5', 'A', '按位权展开为 8+2=10。'),
       (17, 32, 'MULTIPLE', 'GPIO 引脚在芯片支持及正确配置下可以用于哪些操作？', '读取按键电平', '输出高低电平',
        '直接存放无限数据', '无需驱动直接带动任意大功率电机', 'AB',
        'GPIO 可以读取和输出电平，大功率负载需适当驱动电路。'),
