CREATE TABLE `question_knowledge`
(
    `question_id`  bigint NOT NULL,
    `knowledge_id` bigint NOT NULL,
    PRIMARY KEY (`question_id`, `knowledge_id`),
    KEY `idx_knowledge_question` (`knowledge_id`, `question_id`),
    CONSTRAINT `question_knowledge_ibfk_1` FOREIGN KEY (`question_id`) REFERENCES `question` (`id`),
    CONSTRAINT `question_knowledge_ibfk_2` FOREIGN KEY (`knowledge_id`) REFERENCES `knowledge_point` (`id`)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_0900_ai_ci;
